edits.after:
// Raw customer review/contact data is private. The Customer public review
// wall uses the existing bounded, sanitized server projection instead.
match /reviews/{reviewId} {
  function inquiryReviewOwn(data) {
    return isSignedIn() && reqProvider() == 'google.com' && reqVerified() == true
      && request.auth.token.get('email','') != '' && data.get('email','') == reqEmail();
  }
  function inquiryReviewHQ(data) {
    return isOwner() || companyFreshHQCan(['all','customerapp'],data.get('branch','All'));
  }
  function inquiryReviewCreate(data) {
    let source = readData('incoming_orders',data.orderId);
    return inquiryReviewOwn(data) && reviewId == 'review-' + data.orderId
      && data.orderId is string && data.orderId.matches('^[A-Za-z0-9_-]{1,128}$')
      && data.keys().hasOnly(['version','orderId','orderCode','branch','orderType','sourceItems','totalItemsCount','text','timestamp','customer','email','status','isPublished'])
      && data.version == 1 && source.status == 'completed' && source.customerEmail == reqEmail()
      && data.orderCode == source.orderCode && data.branch == source.branch
      && data.orderType == source.orderType && data.customer == source.customerName
      && data.sourceItems == source.items && data.sourceItems is list
      && data.sourceItems.size() > 0 && data.sourceItems.size() <= 100
      && data.totalItemsCount == source.items.size() && data.text is string
      && data.text.trim().size() > 0 && data.text.size() <= 1500
      && data.timestamp == reqTime() && data.status == 'Pending' && data.isPublished == false
      && nextData('incoming_orders',data.orderId).reviewPrompted == true;
  }
  allow get: if resource == null
    ? isSignedIn() && reqProvider() == 'google.com' && reqVerified() == true
    : inquiryReviewOwn(oldData()) || inquiryReviewHQ(oldData());
  allow list: if inquiryReviewOwn(oldData()) || inquiryReviewHQ(oldData());
  allow create: if inquiryReviewCreate(newData());
  allow update: if inquiryReviewHQ(oldData())
    && newData().diff(oldData()).affectedKeys().hasOnly(['isPublished','status'])
    && newData().isPublished is bool
    && newData().status == (newData().isPublished ? 'Approved' : 'Hidden');
  allow delete: if false;
}
match /customer_feedback/{id} {
  allow create: if newData().keys().hasOnly(['text','timestamp','customerName','email'])
    && newData().size() == 4 && newData().text is string
    && newData().text.trim().size() > 0 && newData().text.size() <= 4000
    && newData().customerName is string && newData().customerName.size() <= 200
    && newData().email is string && newData().email.size() <= 254
    && newData().timestamp == reqTime();
  allow read: if isOwner() || companyFreshHQCan(['all','reviews'],'All');
  allow update, delete: if false;
}
match /franchise_leads/{id} {
  allow create: if newData().keys().hasOnly(['name','phone','email','location','formatInterest','status','timestamp'])
    && newData().size() == 7 && newData().name is string
    && newData().name.trim().size() >= 2 && newData().name.size() <= 100
    && newData().phone is string && newData().phone.size() >= 10 && newData().phone.size() <= 30
    && newData().email is string && newData().email.size() <= 254
    && newData().location is string && newData().location.trim().size() >= 2 && newData().location.size() <= 160
    && newData().formatInterest in ['cart','kiosk','store','undecided']
    && newData().status == 'Pending' && newData().timestamp == reqTime();
  allow read: if isOwner() || companyFreshHQCan(['all','crm'],'All');
  allow update: if (isOwner() || companyFreshHQCan(['all','crm'],'All'))
    && newData().diff(oldData()).affectedKeys().hasOnly(['status'])
    && newData().status == 'Contacted';
  allow delete: if false;
}
